SELECT T2.ID, T2.NOME, COUNT(*) N FROM VIDEO_TEMAS A JOIN VIDEO_TEMAS B ON B.VIDEO_ID = A.VIDEO_ID AND B.TEMA_ID <> A.TEMA_ID JOIN TEMAS T2 ON T2.ID = B.TEMA_ID JOIN VIDEOS V ON V.ID = A.VIDEO_ID WHERE A.TEMA_ID = {{temaId}} AND T2.NOME NOT LIKE 'mentor: %' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) GROUP BY T2.ID, T2.NOME ORDER BY N DESC LIMIT 8